+      [&callback_called](std::unique_ptr<const CanFrame>/*frame*/)
+      {
+        callback_called = true;
+      });
+    REQUIRE(adapter.startReceptionThread());
+
+    CanFrame frame;
+    frame.set_can_id(0x123);
+    frame.set_len(4);
